import { Component, Match, Show, Switch, type JSX } from "solid-js";

import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { IsControllerActive } from "#core/ui-next/services/input.js";

import { PoliciesModel } from "#base/ui/policies/model-policies.js";
import {
	getAdditionalPolicyIcon,
	getCivBGFromPolicy,
	getCivIconFromPolicy,
	policiesFocus,
	setPolicySlotsFocused,
	setTraditionSlotsFocused,
	traditionsFocus,
} from "#base/ui/policies/policies-support.js";

export interface PolicyCardProps extends JSX.HTMLAttributes<HTMLElement> {
	ref?: HTMLDivElement | ((el: HTMLDivElement) => void);
	name?: string;
	description?: string;
	card: TraditionDefinition;
	isActive: boolean;
	tradSlot: boolean;
	isTradition: boolean;
	isNewCard: boolean;
	autoFocus?: boolean;
}

interface UtilityPolicyProps extends JSX.HTMLAttributes<HTMLElement> {
	ref?: HTMLDivElement | ((el: HTMLDivElement) => void);
	card: TraditionDefinition;
	tradSlot: boolean;
	isSlot?: boolean;
}
interface BGProps extends JSX.HTMLAttributes<HTMLElement> {
	bgImage?: string;
}

interface CardSlotProps extends JSX.HTMLAttributes<HTMLElement> {
	ref?: HTMLDivElement | ((el: HTMLDivElement) => void);
	card?: TraditionDefinition;
	isSlot?: boolean;
	slotType: string;
}

interface DotProps extends JSX.HTMLAttributes<HTMLElement> {
	class: string;
	visible: boolean;
}

export const PolicyCard: Component<PolicyCardProps> = (props) => {
	const model = PoliciesModel.get();

	function disableClick(): boolean {
		if (
			(props.card.CultureSlotType == "TRADITION_CULTURE_SLOT" && model.canSwapPolicies) ||
			(props.card.CultureSlotType == "POLICY_CULTURE_SLOT" && model.canSwapPolicies)
		) {
			return false;
		}
		if (props.card.CultureSlotType == "CRISIS_CULTURE_SLOT" && model.canSwapCrisis) {
			return false;
		}

		return true;
	}

	function setFocusStyles(mouseEnter: boolean) {
		const slotType = props.card.CultureSlotType;
		if (props.isActive) {
			return;
		}
		if (slotType == "TRADITION_CULTURE_SLOT" && mouseEnter) {
			setTraditionSlotsFocused(true);
		}
		if (slotType == "TRADITION_CULTURE_SLOT" && !mouseEnter) {
			setTraditionSlotsFocused(false);
		}
		if (slotType == "POLICY_CULTURE_SLOT" && mouseEnter) {
			setPolicySlotsFocused(true);
		}
		if (slotType == "POLICY_CULTURE_SLOT" && !mouseEnter) {
			setPolicySlotsFocused(false);
		}
	}

	function focusableNotActivatable(): boolean {
		return disableClick() && IsControllerActive();
	}

	function cardCannotMove(): boolean {
		if (props.isActive) {
			return false;
		}

		return !model.canSlotCard(props.card);
	}

	return (
		<AudioContextProvider segment="PolicyCard">
			<Activatable
				{...props}
				ref={props.ref}
				disabled={(disableClick() && !IsControllerActive()) || cardCannotMove()}
				class={`flex flex-col my-1 relative text-accent-1 policy-base-card ${props.isActive ? "ml-4" : "ml-2"} ${!props.card.Name ? "opacity-0" : ""} ${props.card.CultureSlotType == "TRADITION_CULTURE_SLOT" ? "tradition-base-bg" : props.card.CultureSlotType == "CRISIS_CULTURE_SLOT" ? "crisis-base-bg" : "policy-base-bg"}`}
				onActivate={() => [
					focusableNotActivatable() ? null : model.onCardClick(props.card, props.isActive, props.tradSlot),
				]}
				onMouseOver={() => setFocusStyles(true)}
				onMouseLeave={() => setFocusStyles(false)}
				onFocus={() => setFocusStyles(true)}
				onBlur={() => setFocusStyles(false)}
				disableFocus={!props.card.Name}
				autoFocus={props.autoFocus}
				audioComponentAlias={
					focusableNotActivatable() || !props.card ? "" : props.isActive ? "Assigned" : "Unassigned"
				}
			>
				<div
					class={"size-full absolute"}
					data-info-name="resize-container"
					{...props}
				/>
				<Show when={props.isTradition}>
					<BackgroundImage bgImage={getCivBGFromPolicy(props.card)} />
				</Show>
				<DecorativeFrame />
				<div class="flex flex-row flex-auto">
					<IconPod {...props} />
					<div class={"flex flex-auto flex-col p-4"}>
						<div class="relative w-full justify-start items-center flex flex-row">
							<Show when={props.isTradition}>
								<Icon
									class="tradition-civ-icon"
									name={`url('blp:${getCivIconFromPolicy(props.card) ?? ""}')`}
									isUrl={true}
								/>
							</Show>
							<Show when={getAdditionalPolicyIcon(props.card) != ""}>
								<Icon
									class="tradition-civ-icon mr-1"
									name={`url('blp:${getAdditionalPolicyIcon(props.card) ?? ""}')`}
									isUrl={true}
								/>
							</Show>
							<L10n.Stylize
								text={props.name ?? ""}
								class="flex flex-auto font-title uppercase tracking-100 break-words text-sm font-bold"
							/>
						</div>
						<DividerGradient {...props} />
						<L10n.Stylize
							text={props.description ?? ""}
							class={"text-sm relative text-left text-accent-2"}
						/>
					</div>
				</div>
				<NewDot
					class={"absolute top-1\\.5 right-1\\.5"}
					visible={props.isNewCard}
				/>
			</Activatable>
		</AudioContextProvider>
	);
};
export const DisplayPolicyCard: Component<PolicyCardProps> = (props) => {
	return (
		<div
			{...props}
			ref={props.ref}
			class={`flex flex-col my-1 ml-1 relative text-accent-1 policy-base-card gov-overview mr-3\\.5 ${!props.card.Name ? "opacity-0" : ""} ${props.card.CultureSlotType == "TRADITION_CULTURE_SLOT" ? "tradition-base-bg" : props.card.CultureSlotType == "CRISIS_CULTURE_SLOT" ? "crisis-base-bg" : "policy-base-bg"}`}
		>
			<div
				class={"size-full absolute"}
				data-info-name="resize-container"
				{...props}
			/>
			<Show when={props.isTradition}>
				<BackgroundImage bgImage={getCivBGFromPolicy(props.card)} />
			</Show>
			<DecorativeFrame />
			<div class="flex flex-row flex-auto">
				<IconPod {...props} />
				<div class={"flex flex-auto flex-col p-4"}>
					<div class="relative w-full justify-start items-center flex flex-row">
						<Show when={props.isTradition}>
							<Icon
								class="tradition-civ-icon"
								name={`url('blp:${getCivIconFromPolicy(props.card) ?? ""}')`}
								isUrl={true}
							/>
						</Show>

						<L10n.Stylize
							text={props.name ?? ""}
							class="flex flex-auto font-title uppercase tracking-100 break-words text-sm font-bold"
						/>
					</div>
					<DividerGradient {...props} />
					<L10n.Stylize
						text={props.description ?? ""}
						class={"text-sm relative text-left text-accent-2"}
					/>
				</div>
			</div>
			<NewDot
				class={"absolute top-1\\.5 right-1\\.5"}
				visible={props.isNewCard}
			/>
		</div>
	);
};

export const CardSlot: Component<CardSlotProps> = (props) => {
	function getSlotStyles(): string {
		return policiesFocus()
			? "policy-slot-bg empty-base-bg-highlight"
			: traditionsFocus() && props.slotType == "TRADITION_CULTURE_SLOT"
				? "tradition-slot-bg empty-base-bg-highlight"
				: "opacity-50 empty-base-bg";
	}

	return (
		<div
			{...props}
			data-name="empty card slot"
			ref={props.ref}
			class={`pointer-events-none my-1 ml-4 relative empty-base-card ${getSlotStyles()}`}
		>
			<div class={`inset-0 absolute empty-card-tint`}>
				<div class={"h-1\\/2 w-full policy-card-frame"} />
				<div class={"h-1\\/2 w-full -scale-y-100 policy-card-frame"} />
			</div>
			<div class="flex flex-row size-full">
				<SlotIconPod
					{...props}
					isSlot={true}
				/>
				<div
					class={
						"flex flex-auto size-full justify-center text-xs font-title tracking-100 uppercase items-center"
					}
				>
					<L10n.Stylize
						class={"text-accent-1"}
						text={
							props.slotType == "TRADITION_CULTURE_SLOT"
								? "LOC_UI_POLICIES_ADD_TRADITION"
								: "LOC_UI_POLICIES_ADD_POLICY"
						}
					/>
				</div>
			</div>
		</div>
	);
};

export const BlankCardSlot: Component<CardSlotProps> = (props) => {
	return (
		<div
			{...props}
			data-name="empty card slot"
			ref={props.ref}
			class={`pointer-events-none my-1 ml-1 mr-4 relative policy-base-card empty-base-bg opacity-0`}
		>
			<div class={`inset-0 absolute empty-card-tint`}>
				<div class={"h-1\\/2 w-full policy-card-frame"} />
				<div class={"h-1\\/2 w-full -scale-y-100 policy-card-frame"} />
			</div>
			<div class="flex flex-row size-full" />
		</div>
	);
};

const DecorativeFrame: Component = () => {
	return (
		<div class={`inset-0 absolute`}>
			<div class={"h-1\\/2 w-full policy-card-frame"} />
			<div class={"h-1\\/2 w-full -scale-y-100 policy-card-frame"} />
		</div>
	);
};

const IconPod: Component<UtilityPolicyProps> = (props) => {
	return (
		<div class={"w-6 flex items-center relative left-0\\.5 ml-px"}>
			<Switch
				fallback={
					<Icon
						class="policy-card-icon-backer left-px absolute bg-left flex items-center"
						name={`url('blp:accent_circle_policy')`}
						isUrl={true}
					>
						<Icon
							class="policy-card-icon -ml-5"
							name={`url('blp:icon_policy')`}
							isUrl={true}
						/>
					</Icon>
				}
			>
				<Match when={props.tradSlot}>
					<div class="flex flex-col relative">
						<Icon
							class={`policy-card-icon-backer left-px absolute bottom-0 bg-left flex items-center ${props.card.CultureSlotType != "TRADITION_CULTURE_SLOT" ? "policy-grayscale" : ""}`}
							name={`url('blp:accent_hex_tradition')`}
							isUrl={true}
						>
							<Icon
								class="policy-card-icon -ml-5"
								name={`${props.card.CultureSlotType == "TRADITION_CULTURE_SLOT" ? "url('blp:icon_tradition')" : "url('blp:icon_tradition_gray')"}`}
								isUrl={true}
							/>
							<Show when={props.card.CultureSlotType != "TRADITION_CULTURE_SLOT"}>
								<Icon
									class="absolute policy-card-icon -ml-5 policy-dark-backer opacity-30"
									name={`${props.card.CultureSlotType == "TRADITION_CULTURE_SLOT" ? "url('blp:icon_tradition')" : "url('blp:icon_tradition_gray')"}`}
									isUrl={true}
								/>
							</Show>
						</Icon>
						<Icon
							class={`policy-card-icon-backer left-px absolute top-0 bg-left flex items-center ${props.card.CultureSlotType != "POLICY_CULTURE_SLOT" ? "policy-grayscale" : ""}`}
							name={`url('blp:accent_circle_policy')`}
							isUrl={true}
						>
							<Show when={props.card.CultureSlotType != "POLICY_CULTURE_SLOT"}>
								<Icon
									class="absolute policy-card-icon -ml-5 policy-dark-backer opacity-30"
									name={`${props.card.CultureSlotType == "POLICY_CULTURE_SLOT" ? "url('blp:icon_policy')" : "url('blp:icon_policy')"}`}
									isUrl={true}
								/>
							</Show>
							<Icon
								class="policy-card-icon -ml-5"
								name={`${props.card.CultureSlotType == "POLICY_CULTURE_SLOT" ? "url('blp:icon_policy')" : "url('blp:icon_policy_gray')"}`}
								isUrl={true}
							/>
						</Icon>
					</div>
				</Match>
				<Match when={props.card.CultureSlotType == "TRADITION_CULTURE_SLOT"}>
					<Icon
						class="policy-card-icon-backer left-px absolute bg-left flex items-center"
						name={`url('blp:accent_hex_tradition')`}
						isUrl={true}
					>
						<Icon
							class="policy-card-icon -ml-5"
							name={`url('blp:icon_tradition')`}
							isUrl={true}
						/>
					</Icon>
				</Match>
				<Match when={props.card.CultureSlotType == "CRISIS_CULTURE_SLOT"}>
					<Icon
						class="policy-card-icon-backer left-px absolute bg-left flex items-center"
						name={`url('blp:accent_triangle_crisis_gray')`}
						isUrl={true}
					>
						<Icon
							class="policy-card-icon -ml-5"
							name={`url('blp:icon_crisis')`}
							isUrl={true}
						/>
					</Icon>
				</Match>
			</Switch>
		</div>
	);
};
const SlotIconPod: Component<CardSlotProps> = (props) => {
	return (
		<div class={"w-6 flex items-center relative left-0\\.5 ml-px"}>
			<Switch
				fallback={
					<Icon
						class={`policy-card-icon-backer left-px absolute bg-left flex items-center ${policiesFocus() ? "" : "policy-grayscale"}`}
						name={`url('blp:accent_circle_policy')`}
						isUrl={true}
					>
						<Icon
							class={`policy-card-icon -ml-5 ${policiesFocus() ? "policies-focus-icon-scale" : "policy-grayscale"}`}
							name={`url('blp:icon_policy')`}
							isUrl={true}
						/>
					</Icon>
				}
			>
				<Match when={props.slotType == "TRADITION_CULTURE_SLOT"}>
					<div class="flex flex-col relative">
						<Icon
							class={`policy-card-icon-backer left-px absolute bottom-0 bg-left flex items-center ${traditionsFocus() ? "" : "policy-grayscale"}`}
							name={`url('blp:accent_hex_tradition')`}
							isUrl={true}
						>
							<Icon
								class={`policy-card-icon -ml-5 ${traditionsFocus() ? "policies-focus-icon-scale" : ""}`}
								name={`url('blp:icon_tradition')`}
								isUrl={true}
							/>
						</Icon>
						<Icon
							class={`policy-card-icon-backer left-px absolute top-0 bg-left flex items-center ${policiesFocus() ? "" : "policy-grayscale"}`}
							name={`url('blp:accent_circle_policy')`}
							isUrl={true}
						>
							<Icon
								class={`policy-card-icon -ml-5 ${policiesFocus() ? "policies-focus-icon-scale" : ""}`}
								name={`url('blp:icon_policy')`}
								isUrl={true}
							/>
						</Icon>
					</div>
				</Match>

				<Match when={props.slotType == "CRISIS_CULTURE_SLOT"}>
					<Icon
						class="policy-card-icon-backer left-px absolute bg-left flex items-center"
						name={`url('blp:accent_triangle_crisis_gray')`}
						isUrl={true}
					>
						<Icon
							class="policy-card-icon -ml-5"
							name={`url('blp:icon_crisis')`}
							isUrl={true}
						/>
					</Icon>
				</Match>
			</Switch>
		</div>
	);
};
const BackgroundImage: Component<BGProps> = (props) => {
	return (
		<div class={"inset-0 absolute"}>
			<div
				class={"size-full absolute policy-card-bg-image"}
				data-name="tradition-card-bg"
				style={{
					"background-image": `url('${props.bgImage}')`,
					"background-size": "cover",
					"background-position-x": "50%",
				}}
			/>
			<div
				class={"size-full"}
				data-name="tradition-card-bg-overlay"
				style={{
					"background-image": `url('blp:frame_policy_tradition_dark')`,
					"background-size": "cover",
					"background-position-x": "50%",
				}}
			/>
		</div>
	);
};

const DividerGradient: Component<UtilityPolicyProps> = (props) => {
	function getBG() {
		if (props.card.CultureSlotType == "TRADITION_CULTURE_SLOT") {
			return "linear-gradient(to right, rgba(162, 147, 122, 1), rgba(162, 147, 122, 0))";
		} else {
			return "linear-gradient(to right, rgba(121, 134, 146, 1), rgba(121, 134, 146, 0))";
		}
	}
	return (
		<div class={"w-full py-2"}>
			<div
				class={"flex h-px w-full"}
				style={{
					"background-image": getBG(),
				}}
			/>
		</div>
	);
};

const NewDot: Component<DotProps> = (props) => {
	return (
		<Show when={props.visible}>
			<div class={`size-3\\.5 ${props.class}`}>
				<div
					class={`relative size-full bg-cover bg-center bg-no-repeat new-dot-tint`}
					style={{ "background-image": "url(blp:new_dot_base)" }}
				/>
				<div
					class={`absolute inset-1 bg-cover bg-center bg-no-repeat`}
					style={{ "background-image": "url(blp:new_dot_highlite)" }}
				/>
			</div>
		</Show>
	);
};
